package kr.yunseok.touchmacro;
import java.lang.reflect.*;
import org.junit.Test;
import static org.junit.Assert.*;

/** 준비 완료와 실제 최초 전달 허가를 구분하는 고정 경계 검사입니다. */
public class AiFirstInputPermitTest {
    private Object permit(long window)throws Exception{return Class.forName("kr.yunseok.touchmacro.AiFirstInputPermit").getConstructor(String.class,long.class,long.class,long.class).newInstance("com.example.target",7L,2L,window);}
    private Object call(Object value,String method,Class<?>[] types,Object...args)throws Exception{try{return value.getClass().getMethod(method,types).invoke(value,args);}catch(InvocationTargetException error){throw (Exception)error.getCause();}}
    private boolean confirm(Object value,String pkg,long generation,long pause,long window,boolean paused)throws Exception{return (Boolean)call(value,"confirm",new Class<?>[]{String.class,long.class,long.class,long.class,boolean.class},pkg,generation,pause,window,paused);}
    private boolean dispatch(Object value,long generation,long pause,long window,boolean paused)throws Exception{return (Boolean)call(value,"permitsDispatch",new Class<?>[]{long.class,long.class,long.class,boolean.class},generation,pause,window,paused);}
    @Test public void anOldGateObservationAloneNeverAuthorizesDispatch()throws Exception{Object permit=permit(10);assertFalse(dispatch(permit,7,2,10,false));}
    @Test public void aDifferentUidAfterTheGateOpensCannotReceiveTheFirstGesture()throws Exception{Macro macro=new Macro();macro.steps.add(new Step("TAP"));AiStartGate gate=AiStartGate.macro(macro,"com.example.target","kr.yunseok.touchmacro");assertTrue(gate.observe("com.example.target",false));Object permit=permit(10);assertFalse(confirm(permit,"com.example.other",7,2,10,false));assertFalse(dispatch(permit,7,2,10,false));}
    @Test public void ownHudHideBeforeFreshQueryIsAllowedAndNormalDispatchOccursExactlyOnce()throws Exception{long beforePrepare=10,afterOwnHudHide=beforePrepare+1;Object permit=permit(afterOwnHudHide);assertTrue(confirm(permit,"com.example.target",7,2,afterOwnHudHide,false));int count=0;if(dispatch(permit,7,2,afterOwnHudHide,false)){count++;call(permit,"dispatched",new Class<?>[]{});}if(dispatch(permit,7,2,afterOwnHudHide,false))count++;assertEquals(1,count);}
    @Test public void aWindowChangeDuringFreshTargetReadInvalidatesItsObservation()throws Exception{Object permit=permit(10);assertFalse(confirm(permit,"com.example.target",7,2,11,false));assertFalse(dispatch(permit,7,2,11,false));}
    @Test public void aWindowChangeAfterFreshReadAndBeforeDispatchDeliversNothing()throws Exception{Object permit=permit(10);assertTrue(confirm(permit,"com.example.target",7,2,10,false));assertFalse(dispatch(permit,7,2,11,false));}
    @Test public void pauseRevisionAndNewGenerationRejectPreparedInput()throws Exception{Object permit=permit(10);assertTrue(confirm(permit,"com.example.target",7,2,10,false));assertFalse(dispatch(permit,7,2,10,true));assertFalse(dispatch(permit,7,3,10,false));assertFalse(dispatch(permit,8,2,10,false));assertFalse(confirm(permit,"com.example.target",7,3,10,false));}
    @Test public void explicitAppUpdatesOnlyTheUnconsumedInputTargetAndDoesNotChangeTheMacro()throws Exception{Macro macro=new Macro();Step tap=new Step("TAP");macro.steps.add(tap);AiStartGate gate=AiStartGate.macro(macro,"com.example.target","kr.yunseok.touchmacro");Step app=new Step("APP");app.packageName="com.example.next";assertEquals("com.example.target",call(gate,"inputTarget",new Class<?>[]{}));call(gate,"appSucceeded",new Class<?>[]{Step.class},app);assertEquals("com.example.next",call(gate,"inputTarget",new Class<?>[]{}));call(gate,"inputDispatched",new Class<?>[]{});assertEquals("",call(gate,"inputTarget",new Class<?>[]{}));call(gate,"appSucceeded",new Class<?>[]{Step.class},app);assertEquals("",call(gate,"inputTarget",new Class<?>[]{}));assertSame(tap,macro.steps.get(0));assertEquals(1,macro.steps.size());}
    @Test public void explicitAppAfterZeroDelayWaitsForOnlyItsOwnTransition()throws Exception{Macro macro=new Macro();macro.steps.add(new Step("WAIT"));AiStartGate gate=AiStartGate.macro(macro,"com.example.previous","kr.yunseok.touchmacro");Step app=new Step("APP");app.packageName="com.example.next";app.after=0;gate.appSucceeded(app);assertTrue(gate.awaitingInputApp());assertFalse(gate.observeInputApp("com.example.previous"));assertFalse(gate.observeInputApp("kr.yunseok.touchmacro"));assertFalse(gate.observeInputApp(""));assertTrue(gate.observeInputApp("com.example.next"));assertFalse(gate.awaitingInputApp());assertEquals(0,app.after);}
    @Test public void aThirdAppCannotBeAcceptedAsAnExplicitAppTransition()throws Exception{Macro macro=new Macro();macro.steps.add(new Step("WAIT"));AiStartGate gate=AiStartGate.macro(macro,"com.example.previous","kr.yunseok.touchmacro");Step app=new Step("APP");app.packageName="com.example.next";gate.appSucceeded(app);try{gate.observeInputApp("com.example.third");fail("제3앱을 명시 전환으로 수락했습니다");}catch(IllegalArgumentException expected){}assertTrue(gate.awaitingInputApp());}
}
